package config

import (
	"context"
	"fmt"
	"time"

	"gopkg.in/yaml.v2"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	"k8s.io/client-go/tools/clientcmd"

	"github.com/everoute/everoute/plugin/tower/pkg/client"
)

// Config of everoute e2e framework
type Config struct {
	// KubeConfig connect to kube-apiserver
	KubeConfig *rest.Config `yaml:"kube-config,omitempty"`
	// TowerClient connect to tower
	TowerClient *client.Client `yaml:"tower-client,omitempty"`

	Endpoint EndpointConfig `yaml:"endpoint"`
	IPAM     *IPAMConfig    `yaml:"ipam,omitempty"`
	Nodes    []NodeConfig   `yaml:"nodes,omitempty"`
	Timeout  *time.Duration `yaml:"timeout,omitempty"`
	Interval *time.Duration `yaml:"interval,omitempty"`
}

type NodeConfig struct {
	Name           string   `yaml:"name"`
	Roles          []string `yaml:"roles,omitempty"`
	User           string   `yaml:"user,omitempty"`
	DialAddress    string   `yaml:"dial-address,omitempty"`
	Password       *string  `yaml:"password,omitempty"`
	PrivateKeyData *string  `yaml:"private-key-data,omitempty"`
	BridgeName     *string  `yaml:"bridge-name,omitempty"`
}

type EndpointConfig struct {
	// if provider is netns and kubeConfig is empty, config.KubeConfig will use
	KubeConfig *rest.Config `yaml:"kube-config,omitempty"`
	// if provider is tower and towerClient is empty, config.TowerClient will use
	TowerClient *client.Client `yaml:"tower-client,omitempty"`

	// Endpoint Provider, must "tower", "netns" or nil, default netns
	Provider *string `yaml:"provider,omitempty"`
	// template for create vm, only valid when provider is tower
	VMTemplateID *string `yaml:"vm-template-id,omitempty"`
	// create vm in the specify vds, only valid when provider is tower
	VdsID *string `yaml:"vds-id,omitempty"`
}

type IPAMConfig struct {
	IPRange string `yaml:"ip-range"`
}

func LoadDefault(kubeConfig string) (*Config, error) {
	var defaultConfigMap = types.NamespacedName{Namespace: metav1.NamespaceSystem, Name: `everoute-e2e-framework-config`}
	return LoadFromConfigMap(kubeConfig, defaultConfigMap)
}

func LoadFromConfigMap(kubeConfig string, namespacedName types.NamespacedName) (*Config, error) {
	var config Config
	var err error

	config.KubeConfig, err = clientcmd.BuildConfigFromFlags("", kubeConfig)
	if err != nil {
		return nil, err
	}

	kubeClientset, err := kubernetes.NewForConfig(config.KubeConfig)
	if err != nil {
		return nil, err
	}

	configMap, err := kubeClientset.CoreV1().ConfigMaps(namespacedName.Namespace).Get(context.Background(), namespacedName.Name, metav1.GetOptions{})
	if err != nil {
		return nil, err
	}

	err = yaml.Unmarshal([]byte(configMap.Data["config"]), &config)
	if err != nil {
		return nil, err
	}

	return verifyAndComplete(&config)
}

func verifyAndComplete(config *Config) (*Config, error) {
	if config.KubeConfig == nil {
		return nil, fmt.Errorf("kubeconfig must set in config")
	}

	if config.Endpoint.KubeConfig == nil {
		config.Endpoint.KubeConfig = config.KubeConfig
	}
	if config.Endpoint.TowerClient == nil {
		config.Endpoint.TowerClient = config.TowerClient
	}

	if config.Endpoint.Provider != nil && *config.Endpoint.Provider == "tower" {
		if config.Endpoint.TowerClient == nil {
			return nil, fmt.Errorf("tower client must set when provider is tower")
		}
		if config.Endpoint.VMTemplateID == nil {
			return nil, fmt.Errorf("vmTemplateID must set when provider is tower")
		}
		if config.Endpoint.VdsID == nil {
			return nil, fmt.Errorf("vdsID must set when provider is tower")
		}
		if _, err := config.Endpoint.TowerClient.Auth(); err != nil {
			return nil, fmt.Errorf("could not login tower %s", config.Endpoint.TowerClient.URL)
		}
	}

	if config.IPAM == nil {
		config.IPAM = &IPAMConfig{IPRange: "10.0.0.0/24"}
	}

	var (
		defaultTimeout  = time.Second * 20
		defaultInterval = time.Millisecond * 250
	)

	if config.Timeout == nil {
		config.Timeout = &defaultTimeout
	}

	if config.Interval == nil {
		config.Interval = &defaultInterval
	}

	return config, nil
}

package qqwry

import (
	"encoding/binary"
	"errors"
	"io/ioutil"
	"log"
	"net"
	"os"
	"strings"
	"time"

	"golang.org/x/text/encoding/simplifiedchinese"
)

// qqwry.LoadData("data/qqwry.dat")
// rs := qqwry.Find("172.16.17.32")
// log.Println(rs)

const (
	// IndexLen 索引长度
	IndexLen = 7
	// RedirectMode1 国家的类型, 指向另一个指向
	RedirectMode1 = 0x01
	// RedirectMode2 国家的类型, 指向一个指向
	RedirectMode2 = 0x02
)

// ResultQQwry 归属地信息
type ResultQQwry struct {
	IP      string `json:"ip"`
	Country string `json:"country"`
	Area    string `json:"area"`
}

type fileData struct {
	Data     []byte
	FilePath string
	Path     *os.File
	IPNum    int64
}

// QQwry 纯真ip库
type QQwry struct {
	Data   *fileData
	Offset int64
}

func LoadData(datFile string) {
	IPData.FilePath = datFile
	startTime := time.Now().UnixNano()
	res := IPData.InitIPData()
	if v, ok := res.(error); ok {
		log.Panic(v)
	}
	endTime := time.Now().UnixNano()
	log.Printf("IP 库加载完成 共加载:%d 条 IP 记录, 所花时间:%.1f ms\n", IPData.IPNum, float64(endTime-startTime)/1000000)
}

// IPData IP库的数据
var IPData fileData
var q = NewQQwry()

func Find(ip string) (res ResultQQwry) {
	return q.Find(ip)
}
func FindIPs(ips []string) (rs map[string]ResultQQwry) {
	return q.FindIPs(ips)
}

// InitIPData 初始化ip库数据到内存中
func (f *fileData) InitIPData() (rs interface{}) {

	// 判断文件是否存在
	_, err := os.Stat(f.FilePath)
	if err != nil && os.IsNotExist(err) {
		rs = errors.New("文件不存在")
		return
	}

	// 打开文件句柄
	f.Path, err = os.OpenFile(f.FilePath, os.O_RDONLY, 0400)
	if err != nil {
		rs = err
		return
	}
	defer f.Path.Close()

	tmpData, err := ioutil.ReadAll(f.Path)
	if err != nil {
		log.Println(err)
		rs = err
		return
	}

	f.Data = tmpData

	buf := f.Data[0:8]
	start := binary.LittleEndian.Uint32(buf[:4])
	end := binary.LittleEndian.Uint32(buf[4:])

	f.IPNum = int64((end-start)/IndexLen + 1)

	return true
}

// NewQQwry 新建 qqwry  类型
func NewQQwry() QQwry {
	return QQwry{
		Data: &IPData,
	}
}

// ReadData 从文件中读取数据
func (q *QQwry) ReadData(num int, offset ...int64) (rs []byte) {
	if len(offset) > 0 {
		q.SetOffset(offset[0])
	}
	nums := int64(num)
	end := q.Offset + nums
	dataNum := int64(len(q.Data.Data))
	if q.Offset > dataNum {
		return nil
	}

	if end > dataNum {
		end = dataNum
	}
	rs = q.Data.Data[q.Offset:end]
	q.Offset = end
	return
}

// SetOffset 设置偏移量
func (q *QQwry) SetOffset(offset int64) {
	q.Offset = offset
}
func (q *QQwry) FindIPs(ips []string) (rs map[string]ResultQQwry) {
	rs = map[string]ResultQQwry{}
	if len(ips) > 0 {
		for _, v := range ips {
			rs[v] = q.Find(v)
		}
	}
	return
}

// Find ip地址查询对应归属地信息
func (q *QQwry) Find(ip string) (res ResultQQwry) {

	res = ResultQQwry{}

	res.IP = ip
	if strings.Count(ip, ".") != 3 {
		return res
	}
	offset := q.searchIndex(binary.BigEndian.Uint32(net.ParseIP(ip).To4()))
	if offset <= 0 {
		return
	}

	var country []byte
	var area []byte

	mode := q.readMode(offset + 4)
	if mode == RedirectMode1 {
		countryOffset := q.readUInt24()
		mode = q.readMode(countryOffset)
		if mode == RedirectMode2 {
			c := q.readUInt24()
			country = q.readString(c)
			countryOffset += 4
		} else {
			country = q.readString(countryOffset)
			countryOffset += uint32(len(country) + 1)
		}
		area = q.readArea(countryOffset)
	} else if mode == RedirectMode2 {
		countryOffset := q.readUInt24()
		country = q.readString(countryOffset)
		area = q.readArea(offset + 8)
	} else {
		country = q.readString(offset + 4)
		area = q.readArea(offset + uint32(5+len(country)))
	}

	enc := simplifiedchinese.GBK.NewDecoder()
	res.Country, _ = enc.String(string(country))
	res.Area, _ = enc.String(string(area))

	return
}

// readMode 获取偏移值类型
func (q *QQwry) readMode(offset uint32) byte {
	mode := q.ReadData(1, int64(offset))
	return mode[0]
}

// readArea 读取区域
func (q *QQwry) readArea(offset uint32) []byte {
	mode := q.readMode(offset)
	if mode == RedirectMode1 || mode == RedirectMode2 {
		areaOffset := q.readUInt24()
		if areaOffset == 0 {
			return []byte("")
		}
		return q.readString(areaOffset)
	}
	return q.readString(offset)
}

// readString 获取字符串
func (q *QQwry) readString(offset uint32) []byte {
	q.SetOffset(int64(offset))
	data := make([]byte, 0, 30)
	buf := make([]byte, 1)
	for {
		buf = q.ReadData(1)
		if buf[0] == 0 {
			break
		}
		data = append(data, buf[0])
	}
	return data
}

// searchIndex 查找索引位置
func (q *QQwry) searchIndex(ip uint32) uint32 {
	header := q.ReadData(8, 0)

	start := binary.LittleEndian.Uint32(header[:4])
	end := binary.LittleEndian.Uint32(header[4:])

	buf := make([]byte, IndexLen)
	mid := uint32(0)
	_ip := uint32(0)

	for {
		mid = q.getMiddleOffset(start, end)
		buf = q.ReadData(IndexLen, int64(mid))
		_ip = binary.LittleEndian.Uint32(buf[:4])

		if end-start == IndexLen {
			offset := byteToUInt32(buf[4:])
			buf = q.ReadData(IndexLen)
			if ip < binary.LittleEndian.Uint32(buf[:4]) {
				return offset
			}
			return 0
		}

		// 找到的比较大，向前移
		if _ip > ip {
			end = mid
		} else if _ip < ip { // 找到的比较小，向后移
			start = mid
		} else if _ip == ip {
			return byteToUInt32(buf[4:])
		}
	}
}

// readUInt24
func (q *QQwry) readUInt24() uint32 {
	buf := q.ReadData(3)
	return byteToUInt32(buf)
}

// getMiddleOffset
func (q *QQwry) getMiddleOffset(start uint32, end uint32) uint32 {
	records := ((end - start) / IndexLen) >> 1
	return start + records*IndexLen
}

// byteToUInt32 将 byte 转换为uint32
func byteToUInt32(data []byte) uint32 {
	i := uint32(data[0]) & 0xff
	i |= (uint32(data[1]) << 8) & 0xff00
	i |= (uint32(data[2]) << 16) & 0xff0000
	return i
}

